"""Thin JSON interface to the pinned CrossBeam search and native DSL."""
import ast
import os
import contextlib
import hashlib
import json
import random
import signal
import sys
import time
import traceback
from types import SimpleNamespace

def emit(value):
    print(json.dumps(value,ensure_ascii=False),flush=True)

def native_run(expression,text):
    from crossbeam.dsl.checker import BUSTLE_OPS_NAMESPACE
    # Only the expression language generated by the native DSL is accepted.
    tree=ast.parse(expression,mode='eval')
    def visit(node):
        if isinstance(node,ast.Expression): return visit(node.body)
        if isinstance(node,ast.Constant) and type(node.value) in (str,int,bool): return node.value
        if isinstance(node,ast.UnaryOp) and isinstance(node.op,ast.USub): return -visit(node.operand)
        if isinstance(node,ast.Name) and node.id=='x': return text
        if isinstance(node,ast.Call) and isinstance(node.func,ast.Name) and not node.keywords and node.func.id in BUSTLE_OPS_NAMESPACE:
            return BUSTLE_OPS_NAMESPACE[node.func.id](*[visit(a) for a in node.args])
        raise ValueError('Unexpected native expression node')
    return visit(tree)

def main():
    import numpy as np
    import torch
    from crossbeam.algorithm import synthesis
    from crossbeam.dsl import domains
    from crossbeam.dsl.task import Task
    from crossbeam.model.joint_model import JointModel
    from crossbeam.model.util import CharacterTable
    torch.set_num_threads(2)
    torch.set_num_interop_threads(1)
    domain=domains.get_domain('bustle')
    args=SimpleNamespace(io_encoder='bustle_sig',value_encoder='bustle_sig',embed_dim=512,max_num_inputs=3,encode_weight=True,step_score_func='mlp',score_normed=True)
    start=time.monotonic()
    with contextlib.redirect_stdout(sys.stderr):
        model=JointModel(args,CharacterTable(domain.input_charset,domain.input_max_len),CharacterTable(domain.output_charset,domain.output_max_len),CharacterTable(domain.value_charset,domain.value_max_len),domain.operations)
        model.load_state_dict(torch.load('/models/crossbeam.ckpt',map_location='cpu'))
        model.eval()
    emit({'event':'ready','system':'S06','initialization_seconds':time.monotonic()-start,'torch_version':torch.__version__,'pythonhashseed':os.environ.get('PYTHONHASHSEED')})
    for line in sys.stdin:
        request=json.loads(line)
        record={'task_id':request.get('task_id'),'system':'S06'}
        start=time.monotonic()
        try:
            if request.get('operation')=='execute':
                outputs=[native_run(request['expression'],x) for x in request['inputs']]
                record.update(status='executed',outputs=outputs)
            else:
                examples=request['examples']
                assert 1 <= len(examples) <= 5
                seed=request.get('seed',20261002)
                random.seed(seed)
                np.random.seed(seed)
                torch.manual_seed(seed)
                task=Task({'x':[e['input'] for e in examples]},[e['output'] for e in examples],solution=None)
                from crossbeam.datasets.bustle_data import bustle_constants_extractor
                record['constant_order']=bustle_constants_extractor(task)
                with torch.no_grad(),contextlib.redirect_stdout(sys.stderr):
                    out,values,stats=synthesis.synthesize(task,domain,model,device='cpu',max_weight=20,k=10,is_training=False,timeout=request.get('timeout_seconds',60),max_values_explored=request.get('max_values_explored',50000),is_stochastic=False,random_beam=False,use_ur=True,masking=True,static_weight=False)
                emit({'event':'search_complete','task_id':request['task_id']})
                record.update(stats=stats,num_unique_values=len(values))
                if out is None: record['status']='no_program_within_budget'
                else:
                    expression=out.expression()
                    restored=[native_run(expression,e['input']) for e in examples]
                    record.update(expression=expression,native_outputs=list(out.values),restored_outputs=restored,program_weight=out.get_weight())
                    record['status']='program' if restored==task.outputs==list(out.values) else 'training_or_reload_mismatch'
        except Exception as error:
            record.update(status='adapter_error',error_type=type(error).__name__,message=str(error),traceback=traceback.format_exc())
        record['elapsed_seconds']=time.monotonic()-start
        emit(record)

if __name__=='__main__': main()
